import React from "react";
import { useState } from "react";
import "./App.scss";
import LoginRegisterForm from "./components/LoginRegisterContainer/LoginRegisterContainer";
import AdminCustomerContainer from "./components/AdminCustomerContainer/AdminCustomerContainer";
import SellerContainer from "./components/SellerContainer/SellerContainer";

function App() {
  const [isUserAuthenticated, setUserAuthorization] = useState(
    sessionStorage.getItem("isUserAuthenticated") === "true" || false
  );
  const [role, setRole] = useState(
    sessionStorage.getItem("role") || "user" // Récupérer le rôle depuis le stockage
  );
  const [customerId, setCustomerId] = useState(
    sessionStorage.getItem("customerId") || undefined
  );

  const setUserAuthenticatedStatus = (userRole, customerId) => {
    setUserAuthorization(true);
    setRole(userRole); // Définir le rôle (admin, seller, user)
    setCustomerId(customerId);
    sessionStorage.setItem("role", userRole); // Sauvegarder dans le stockage
    sessionStorage.setItem("isUserAuthenticated", "true");
  };

  const handleLogout = () => {
    sessionStorage.clear();
    setUserAuthorization(false);
    setRole("user");
    setCustomerId(undefined);
  };

  const navigateToRegisterPage = () => {
    alert("Navigating to Update Profile page...");
    // Implémenter une redirection vers la page de mise à jour du profil si nécessaire
  };

  return (
    <div>
      {!isUserAuthenticated ? (
        <LoginRegisterForm setUserAuthenticatedStatus={setUserAuthenticatedStatus} />
      ) : (
        <>
          <div className="login-button-container">
            <button onClick={navigateToRegisterPage} className="login-button">
              Update Profile
            </button>
            <button onClick={handleLogout} className="login-button">
              Logout
            </button>
          </div>

          {/* Afficher le composant basé sur le rôle */}
          {role === "admin" && (
            <AdminCustomerContainer isAdmin={true} customerId={customerId} />
          )}
          {role === "seller" && <SellerContainer />}
          {role === "user" && (
            <div>
              <h2>Bienvenue, utilisateur !</h2>
              {/* Inclure ici le composant utilisateur si nécessaire */}
            </div>
          )}
        </>
      )}
    </div>
  );
}

export default App;
